INSERT INTO recetas (categoria_id, titulo, descripcion, tiempo_preparacion_minutos, porciones, ingredientes, instrucciones, fecha_alta, fecha_modificacion, activo) VALUES
                                                                                                                                                                        (1, 'Japchae Tradicional', 'Fideos salteados de boniato con verduras y carne de ternera en salsa de soja.', 30, 4, ARRAY['Fideos de boniato (Dangmyeon)', 'Ternera', 'Espinacas', 'Zanahoria', 'Setas Shiitake', 'Salsa de soja'], '1. Cocer los fideos. 2. Saltear las verduras y la carne por separado. 3. Mezclar todo con aceite de sésamo y salsa de soja.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (1, 'Jajangmyeon Clásico', 'Fideos de trigo gruesos cubiertos con una rica salsa de judía negra fermentada.', 35, 2, ARRAY['Fideos de trigo (Chunmein)', 'Pasta de judía negra (Jajang)', 'Cerdo picado', 'Cebolla', 'Calabacín', 'Caldo'], '1. Hervir los fideos. 2. Sofritar la carne con la cebolla y añadir la pasta de judía negra. 3. Servir la salsa sobre los fideos.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (1, 'Rabokki Picante', 'Combinación de tteokbokki (pasteles de arroz) y fideos ramen en salsa picante.', 20, 2, ARRAY['Pastel de arroz coreano', 'Fideos Ramen', 'Salsa Gochujang', 'Cebolleta', 'Caldo de anchoas', 'Huevo cocido'], '1. Hervir el caldo con la salsa gochujang. 2. Añadir los pasteles de arroz y los fideos. 3. Cocinar hasta espesar y servir.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (1, 'Kalguksu de Mariscos', 'Sopa de fideos de trigo cortados a cuchillo con un caldo intenso de mariscos.', 40, 3, ARRAY['Fideos de trigo frescos', 'Almejas', 'Mejillones', 'Calabacín', 'Ajo', 'Caldo de pescado'], '1. Preparar el caldo hirviendo los mariscos. 2. Cocinar los fideos frescos directamente en el caldo. 3. Servir caliente.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (1, 'Bibim Guksu', 'Fideos finos de trigo mezclados en una salsa fría, picante y agridulce.', 15, 2, ARRAY['Fideos somen', 'Kimchi picado', 'Pasta Gochujang', 'Vinagre de arroz', 'Aceite de sésamo', 'Pepino'], '1. Cocer y enfriar los fideos con agua helada. 2. Mezclar los condimentos con el kimchi. 3. Integrar todo y servir.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (1, 'Janchi Guksu', 'Fideos finos en un caldo claro de anchoas, tradicionalmente servidos en banquetes.', 25, 2, ARRAY['Fideos somen', 'Caldo de anchoas y alga kombu', 'Huevo en juliana', 'Zanahoria', 'Salsa de soja preparada'], '1. Hervir los fideos y escurrir. 2. Calentar el caldo claro. 3. Servir los fideos en el caldo con guarnición por encima.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (1, 'Makguksu', 'Fideos de trigo sarraceno servidos fríos con salsa picante y aceite de perilla.', 20, 2, ARRAY['Fideos de sarraceno', 'Pasta de chile', 'Pepino', 'Pera coreana', 'Aceite de perilla', 'Huevo duro'], '1. Cocer los fideos de sarraceno. 2. Preparar la salsa fría. 3. Montar el plato con láminas de pera y pepino.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (1, 'Jjamppong', 'Fideos con mariscos y verduras en un caldo sumamente picante y ahumado.', 45, 3, ARRAY['Fideos de trigo', 'Marisco variado', 'Cerdo', 'Col', 'Gochugaru (chile en polvo)', 'Ajo'], '1. Saltear el cerdo, verduras y chile en polvo. 2. Añadir caldo y mariscos. 3. Verter sobre los fideos cocidos.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (1, 'Kongguksu', 'Fideos de trigo sumergidos en un refrescante caldo frío de soja molida.', 20, 2, ARRAY['Fideos de trigo', 'Soja blanca', 'Semillas de sésamo', 'Piñones', 'Pepino', 'Sal'], '1. Triturar la soja cocida con sésamo y piñones para crear la leche fría. 2. Cocer los fideos. 3. Servir juntos.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (1, 'Japchae de Cerdo Picante', 'Variación moderna de fideos de boniato con carne de cerdo marinada en picante.', 30, 3, ARRAY['Fideos de boniato', 'Lomo de cerdo', 'Pimiento rojo', 'Cebolla', 'Salsa picante coreana', 'Sésamo'], '1. Marinar el cerdo en picante. 2. Saltear con los fideos cocidos y verduras en juliana. 3. Servir con sésamo.', NOW(), NOW(), 'S');
INSERT INTO recetas (categoria_id, titulo, descripcion, tiempo_preparacion_minutos, porciones, ingredientes, instrucciones, fecha_alta, fecha_modificacion, activo) VALUES
                                                                                                                                                                        (2, 'Hamburguesa Clásica de Bratwurst', 'Carne de salchicha bratwurst fresca a la parrilla con chucrut crujiente en pan de Pretzel.', 20, 2, ARRAY['Pan de pretzel', 'Salchicha bratwurst desmenuzada', 'Chucrut', 'Mostaza alemana', 'Queso Emmental'], '1. Formar la carne y cocinar a la plancha. 2. Fundir el queso encima. 3. Montar con chucrut y mostaza.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (2, 'Frikadelle Burger', 'Hamburguesa tradicional alemana de albóndiga sazonada con hierbas y cebolla.', 25, 4, ARRAY['Carne picada de ternera y cerdo', 'Pan rallado', 'Cebolla pochada', 'Huevo', 'Mostaza', 'Pan brioche'], '1. Mezclar la carne con cebolla y especias. 2. Formar hamburguesas gruesas y freír. 3. Servir en pan brioche.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (2, 'Schnitzel Burger', 'Filete de cerdo empanado crujiente servido como hamburguesa con salsa de champiñones.', 30, 2, ARRAY['Filete fino de cerdo', 'Pan rallado', 'Huevo', 'Harina', 'Champiñones laminados', 'Salsa de nata'], '1. Empanar y freír el cerdo hasta dorar. 2. Preparar salsa de champiñones. 3. Montar la hamburguesa.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (2, 'Burger Alemana con Obatzda', 'Hamburguesa de ternera con crema de queso bávaro Obatzda y cebolla roja.', 25, 2, ARRAY['Carne de ternera', 'Queso Camembert', 'Queso crema', 'Pimentón', 'Cebolla roja', 'Pan rústico'], '1. Preparar la crema Obatzda mezclando quesos y especias. 2. Cocinar la carne. 3. Untar el queso en el pan.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (2, 'Hamburguesa de Leberkäse', 'Versión alemana con rodaja gruesa de pastel de carne caliente y huevo frito.', 15, 2, ARRAY['Leberkäse (pastel de carne alemán)', 'Huevo', 'Pan redondo', 'Mostaza dulce', 'Lechuga'], '1. Dorar la rodaja gruesa de leberkäse en la sartén. 2. Freír un huevo. 3. Ensamblar con mostaza dulce.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (2, 'Burger Vegetal de Lentejas y Setas', 'Hamburguesa saludable de legumbres y setas silvestres con toque de humo.', 30, 3, ARRAY['Lentejas cocidas', 'Setas silvestres', 'Avena', 'Cebolla', 'Especias', 'Pan integral'], '1. Triturar ingredientes y formar medallones. 2. Dorar en sartén con poco aceite. 3. Servir con salsa de yogur.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (2, 'Hamburguesa de Cerdo Asado', 'Inspirada en el Schweinshaxe, con cerdo tierno desmenuzado y salsa de cerveza.', 40, 4, ARRAY['Falda de cerdo asada', 'Cerveza alemana', 'Cebolla', 'Salsa barbacoa', 'Pan de centeno'], '1. Cocinar el cerdo a fuego lento con cerveza. 2. Desmenuzar la carne. 3. Servir generosamente en pan de centeno.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (2, 'Mini Sliders Alemanes', 'Pequeñas hamburguesas con minisalchichas Frankfurt y pepinillos agridulces.', 15, 4, ARRAY['Mini panes', 'Salchichas Frankfurt', 'Pepinillos encurtidos', 'Ketchup', 'Mostaza'], '1. Cortar las salchichas y dorarlas. 2. Montar en los minipanes con pepinillos y salsas.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (2, 'Burger de Ternera con Cebolla a la Cerveza', 'Ternera jugosa con cebolla caramelizada en cerveza negra dunkel.', 30, 2, ARRAY['Carne picada de ternera', 'Cebolla', 'Cerveza oscura', 'Queso Gouda', 'Pan de hamburguesa'], '1. Caramelizar la cebolla con cerveza. 2. Cocinar la carne con queso gouda. 3. Combinar todo.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (2, 'Hamburguesa de Pollo al Estilo Bávaro', 'Pechuga de pollo marinada en hierbas alpinas con manzana salteada.', 25, 2, ARRAY['Pechuga de pollo picada', 'Manzana verde', 'Mantequilla', 'Hojas de salvia', 'Pan'], '1. Saltear manzana en mantequilla. 2. Cocinar la hamburguesa de pollo. 3. Servir con la manzana templada.', NOW(), NOW(), 'S');
INSERT INTO recetas (categoria_id, titulo, descripcion, tiempo_preparacion_minutos, porciones, ingredientes, instrucciones, fecha_alta, fecha_modificacion, activo) VALUES
                                                                                                                                                                        (3, 'Arroz Frito Cantonés', 'Clásico arroz salteado con huevo, guisantes, jamón y cebollino.', 20, 3, ARRAY['Arroz cocido del día anterior', 'Huevo', 'Jamón cocido', 'Guisantes', 'Cebollino', 'Salsa de soja'], '1. Batir y cocinar el huevo rompiéndolo en trocitos. 2. Saltear el arroz con los ingredientes. 3. Añadir soja y servir.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (3, 'Arroz Frito con Pato y Hoisin', 'Arroz salteado aromático acompañado de trozos de pato asado y salsa hoisin.', 25, 2, ARRAY['Arroz blanco', 'Pato asado desmigado', 'Salsa Hoisin', 'Brotes de soja', 'Ajo tierno'], '1. Saltear el pato con el ajo tierno. 2. Incorporar el arroz cocido y la salsa hoisin. 3. Mezclar bien y servir.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (3, 'Arroz con Ternera y Brotes de Bambú', 'Arroz al wok con finas tiras de ternera marinada y bambú crujiente.', 30, 3, ARRAY['Arroz jazmín', 'Ternera en tiras', 'Bambú en conserva', 'Salsa de ostras', 'Jengibre'], '1. Marinar la ternera con salsa de ostras. 2. Saltear al wok con el bambú. 3. Servir sobre una base de arroz jazmín.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (3, 'Arroz Frito Estilo Yangzhou', 'Variedad de arroz frito rico en marisco, cerdo asado, setas y verduras.', 30, 4, ARRAY['Arroz', 'Gambas', 'Cerdo asado (Char Siu)', 'Setas chinas', 'Guisantes', 'Zanahoria'], '1. Cocer el arroz. 2. Saltear las gambas, cerdo y verduras en cubitos. 3. Incorporar el arroz y saltear a fuego vivo.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (3, 'Congee de Arroz con Pollo', 'Gachas de arroz tradicionales chinas, reconfortantes y suaves con jengibre.', 40, 3, ARRAY['Arroz de grano corto', 'Pechuga de pollo', 'Jengibre fresco', 'Cebollino', 'Caldo de pollo'], '1. Cocer el arroz en abundante caldo a fuego lento hasta que se deshaga. 2. Añadir pollo desmenuzado y jengibre. 3. Servir caliente.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (3, 'Arroz Frito Picante con Kimchi', 'Fusión asiática de arroz frito con kimchi fermentado y panceta.', 20, 2, ARRAY['Arroz', 'Kimchi troceado', 'Panceta de cerdo', 'Aceite de sésamo', 'Pasta de chile'], '1. Sofreír la panceta con el kimchi. 2. Añadir el arroz y el jugo de kimchi. 3. Saltear hasta integrar.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (3, 'Arroz al Vapor con Champiñones Shiitake', 'Arroz aromático cocinado al vapor con setas shiitake y salsa de soja oscura.', 35, 3, ARRAY['Arroz glutinoso', 'Setas Shiitake hidratadas', 'Salsa de soja oscura', 'Aceite de sésamo', 'Cebollino'], '1. Macerar las setas con soja. 2. Cocinar el arroz junto con las setas al vapor. 3. Mezclar y servir.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (3, 'Arroz Frito con Gambas y Piña', 'Arroz tropical salteado con trozos de piña fresca y gambas jugosas.', 25, 2, ARRAY['Arroz', 'Gambas peladas', 'Piña fresca', 'Pimiento rojo', 'Caju', 'Curry en polvo'], '1. Saltear las gambas y retirar. 2. Saltear el arroz con la piña y especias. 3. Integrar las gambas y anacardos.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (3, 'Arroz Frito Vegetariano de la Abuela', 'Salteado de arroz con tofu crujiente, maíz, zanahoria y tiras de alga nori.', 20, 3, ARRAY['Arroz', 'Tofu firme', 'Maíz dulce', 'Zanahoria', 'Salsa de soja ligera'], '1. Dorar dados de tofu en la sartén. 2. Añadir verduras y arroz cocido. 3. Saltear con soja ligera.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (3, 'Arroz con Cerdo Agridulce', 'Plato clásico con base de arroz blanco y cerdo rebozado en salsa agridulce.', 35, 3, ARRAY['Arroz blanco', 'Lomo de cerdo rebozado', 'Pimiento', 'Piña', 'Vinagre y azúcar', 'Ketchup'], '1. Freír el cerdo rebozado. 2. Preparar la salsa agridulce con pimiento y piña. 3. Servir el cerdo con su salsa sobre el arroz.', NOW(), NOW(), 'S');
INSERT INTO recetas (categoria_id, titulo, descripcion, tiempo_preparacion_minutos, porciones, ingredientes, instrucciones, fecha_alta, fecha_modificacion, activo) VALUES
                                                                                                                                                                        (4, 'Bacalao al Pil-Pil Tradicional', 'Lomos de bacalao emulsionados en su propia gelatina con aceite de oliva y ajo.', 35, 2, ARRAY['Lomos de bacalao salado', 'Aceite de oliva virgen extra', 'Ajos', 'Guindilla'], '1. Confitar el bacalao a baja temperatura. 2. Retirar el aceite y emulsionar la gelatina moviendo la cazuela en vaivén. 3. Servir caliente.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (4, 'Marmitako de Bonito', 'Guiso marinero tradicional vasco de bonito fresco con patatas y pimiento choricero.', 45, 4, ARRAY['Bonito del norte', 'Patatas', 'Cebolla', 'Pimiento verde', 'Carne de pimiento choricero', 'Caldo de pescado'], '1. Hacer un sofrito con patatas cascadas. 2. Añadir caldo y cocer. 3. Agregar el bonito al final fuera del fuego.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (4, 'Bacalao a la Vizcaína', 'Clásico bacalao en salsa profunda hecha a base de pimiento choricero y cebolla.', 50, 4, ARRAY['Lomos de bacalao', 'Cebollas rojas', 'Carne de pimiento choricero', 'Caldo de pescado', 'Aceite de oliva'], '1. Pochar lentamente la cebolla durante horas. 2. Añadir el choricero para la salsa. 3. Cocinar el bacalao dentro de la salsa.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (4, 'Merluza en Salsa Verde con Almejas', 'Delicados lomos de merluza con almejas en salsa de vino blanco, ajo y perejil fresco.', 30, 3, ARRAY['Rodajas o lomos de merluza', 'Almejas', 'Vino blanco', 'Perejil fresco', 'Ajo', 'Harina'], '1. Hacer una base de ajo, harina y vino blanco. 2. Incorporar la merluza y las almejas hasta abrir. 3. Espolvorear perejil.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (4, 'Besugo al Horno Estilo Orio', 'Besugo asado al horno bañado con un refrito de aceite, ajos dorados y vinagre de sidra.', 35, 2, ARRAY['Besugo entero', 'Ajos', 'Vinagre de sidra', 'Aceite de oliva', 'Guindilla'], '1. Hornear el besugo limpio con un chorro de aceite. 2. Dorar láminas de ajo con guindilla. 3. Verter el refrito sobre el pescado.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (4, 'Txangurro a la Donostiarra', 'Centollo desmenuzado gratinado al horno con verduritas, tomate y un toque de brandy.', 50, 2, ARRAY['Carne de centollo o buey de mar', 'Cebolla', 'Puerro', 'Tomate triturado', 'Brandy', 'Pan rallado'], '1. Cocer y desmigar el marisco. 2. Pochar verduras, añadir la carne y brandy. 3. Rellenar el caparazón y gratinar.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (4, 'Rodaballo Salvaje a la Plancha', 'Lomos de rodaballo jugosos cocinados a la plancha con refrito vasco tradicional.', 25, 2, ARRAY['Lomos de rodaballo', 'Aceite de oliva', 'Ajo laminado', 'Vinagre', 'Sal marina'], '1. Dorar el rodaballo en la plancha por ambos lados. 2. Preparar el refrito de ajos y vinagre. 3. Salsear antes de comer.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (4, 'Kokotxas de Merluza al Pil-Pil', 'Manjar vasco consistente en kokotxas gelatinosas ligadas al pil-pil.', 30, 2, ARRAY['Kokotxas de merluza', 'Aceite de oliva', 'Ajo', 'Guindilla'], '1. Poner las kokotxas con aceite templado. 2. Mover la cazuela constantemente para que suelten su gelatina y liguen.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (4, 'Bonito del Norte Encebollado', 'Rodajas de bonito cocinadas en una jugosa salsa de cebolla pochada y vino blanco.', 35, 3, ARRAY['Rodajas de bonito', 'Cebolla juliana', 'Vino blanco', 'Caldo de pescado', 'Aceite de oliva'], '1. Pochar la cebolla hasta que esté melosa. 2. Sellar el bonito y sumarlo a la cebolla con vino blanco. 3. Cocer unos minutos.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (4, 'Rape a la Plancha con Refrito', 'Medallones firmes de rape con un refrito tradicional de ajos crujientes y guindilla.', 25, 2, ARRAY['Medallones de rape', 'Ajos', 'Guindilla', 'Vinagre de Jerez', 'Aceite'], '1. Cocinar el rape a la plancha. 2. Freír ajos y guindilla con vinagre. 3. Verter por encima.', NOW(), NOW(), 'S');
INSERT INTO recetas (categoria_id, titulo, descripcion, tiempo_preparacion_minutos, porciones, ingredientes, instrucciones, fecha_alta, fecha_modificacion, activo) VALUES
                                                                                                                                                                        (5, 'Paella Valenciana Tradicional', 'La auténtica paella con pollo, conejo, bajoqueta, garrofó y azafrán.', 50, 4, ARRAY['Arroz Bomba', 'Pollo', 'Conejo', 'Judía verde plana (bajoqueta)', 'Garrofó', 'Azafrán'], '1. Dorar las carnes. 2. Añadir verduras, agua y dejar reducir para el caldo. 3. Echar el arroz y cocinar sin remover hasta el socarrat.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (5, 'Arroz a Banda', 'Arroz de pescadores cocido en un potente caldo de pescado y acompañado de alioli.', 40, 4, ARRAY['Arroz Bomba', 'Morralla para caldo', 'Sepia', 'Ñora', 'Ajos', 'Aceite'], '1. Elaborar el caldo de pescado intenso. 2. Sofritar la sepia y la ñora. 3. Cocer el arroz en el caldo y servir con alioli.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (5, 'Arroz Negro con Sepia', 'Arroz jugoso teñido de negro con tinta natural de sepia y sofrito de tomate.', 35, 4, ARRAY['Arroz', 'Sepia fresca', 'Tinta de calamar', 'Cebolla', 'Caldo de pescado', 'Ajo'], '1. Cocinar la sepia troceada. 2. Añadir la tinta y el caldo. 3. Incorporar el arroz y cocinar hasta secar.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (5, 'Arroz al Horno Valenciano', 'Arroz tradicional de cazuela de barro con costillas, embutido, patata y tomate.', 50, 4, ARRAY['Arroz', 'Costilla de cerdo', 'Morcilla', 'Chorizo', 'Patata', 'Garbanzos cocidos', 'Tomete y cabeza de ajo'], '1. Dorar carnes y patatas. 2. Mezclar con el arroz y caldo. 3. Colocar embutido y tomate encima y hornear.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (5, 'Arroz Senyoret con Marisco Pelado', 'Arroz marinero donde todo el marisco viene ya pelado para mayor comodidad.', 35, 3, ARRAY['Arroz', 'Gambas peladas', 'Calamar limpio', 'Mejillones sin concha', 'Fumet de pescado', 'Tomate triturado'], '1. Sofritar el marisco y retirar la mitad. 2. Hacer el sofrito y el caldo. 3. Añadir el arroz y decorar con el marisco reservado.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (5, 'Paella de Verduras de la Huerta', 'Opción vegetariana repleta de alcachofas, judías, coliflor y pimiento.', 35, 4, ARRAY['Arroz', 'Alcachofas', 'Judías verdes', 'Coliflor', 'Pimiento rojo', 'Caldo de verduras'], '1. Sofritar las verduras de temporada. 2. Añadir agua y concentrar el caldo vegetal. 3. Agregar el arroz y cocinar.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (5, 'Arroz Caldoso con Bogavante', 'Exquisito arroz de consistencia caldosa coronado con un bogavante fresco.', 45, 2, ARRAY['Arroz', 'Bogavante', 'Cebolla', 'Tomate', 'Caldo de marisco potente', 'Azafrán'], '1. Sellar el bogavante troceado. 2. Preparar el sofrito y el caldo de marisco. 3. Cocinar el arroz manteniendo textura caldosa.', NOW(), NOW(), 'S'),
                                                                                                                                                                        (5, 'Fideuà de Gandía', 'Versión de la clásica receta valenciana pero elaborada con fideos finos tostados.', 35, 4, ARRAY['Fideos del nº 2', 'Rape', 'Gambas', 'Caldo de pescado', 'Ajo', 'Pimentón dulce'], '1. Tostar los fideos en la paella con aceite. 2. Hacer el sofrito de pescado. 3. Cocinar con el caldo hasta que los fideos queden secos.', NOW(), NOW(), 'S');